import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第五十八章 如来说法如同狮子王吼叫","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/58第五十八章 如来说法如同狮子王吼.md","filePath":"meditation/巴利文大藏经/58第五十八章 如来说法如同狮子王吼.md"}'),o={name:"meditation/巴利文大藏经/58第五十八章 如来说法如同狮子王吼.md"};function r(n,t,i,s,d,c){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="第五十八章-如来说法如同狮子王吼叫" tabindex="-1">第五十八章 如来说法如同狮子王吼叫 <a class="header-anchor" href="#第五十八章-如来说法如同狮子王吼叫" aria-label="Permalink to &quot;第五十八章 如来说法如同狮子王吼叫&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>3.十力品</p><p>相应部12相应21经/十力经(因缘相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，狮子王的吼声让森林中其他飞禽走兽都为之震惊。如来现在为你们说法，如同狮子王大吼的声音，让你们内心震动立刻开启智慧，明白世间的真相和规则。</p><p>如来为你们解答：世间的物质事物，包括世间人的物质身体是如何聚集形成出现的？世间的物质事物，包括世间人的物质身体是如何逐渐衰败、灭亡、消失的？感受是如何聚集形成出现的？感受是如何逐渐衰败、灭亡、消失的？念想是如何聚集形成出现的？念想是如何逐渐衰败、灭亡、消失的？行为是如何聚集形成出现的？行为是如何逐渐衰败、灭亡、消失的？认识、分别、判断是如何聚集形成出现的？认识、分别、判断是如何逐渐衰败、灭亡、消失的？</p><p>弟子们，当这个存在了，以这个的存在为前提条件，那个也会形成存在；当这个产生出现了，以这个的产生出现为前进条件，那个也会产生出现。当这个不存在了，则那个也无法形成存在；当这个不产生出现了，则那个也不会产生出现。也就是这个灭尽了，那个也就被除灭了。弟子们，这个就是缘起法（缘起法解释，见第四十八章、第四十九章）的简要描述。也就是：以「无明」为前提条件产生出「行」，以「行」为前提条件产生出「识」，以「识」为前提条件产生出「名色」，以「名色」为前提条件产生出「六处」，以「六处」为前提条件产生出「触」，以「触」为前提条件产生出「受」，以「受」为前提条件产生出「爱」，以「爱」为前提条件产生出「取」，以「取」为前提条件产生出「有」，以「有」为前提条件产生出「生」，这样有「生」就会产生出忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡。这就是世间人或众生痛苦和烦恼聚集的过程，世间的人或众生按缘起法顺行就会继续的在生死轮回中煎熬沉沦，受尽折磨和痛苦。</p><p>「无明」没有生起「行」就灭除了，「行」没有生起「识」就灭除了，「识」没有生起「名色」就灭除了，「名色」没有生起「六处」就灭除了，「六处」没有生起「触」就灭除了，「触」没有生起「受」就灭除了，「受」没有生起「爱」就灭除了，「爱」没有生起「取」就灭除了，「取」没有生起「有」就灭除了，「有」没有生起「生」就灭除了，「生」没有生起，忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡就灭除了。这就是世间人或众生痛苦和烦恼除灭的过程。世间的人或众生按缘起法的逆行就能从生死轮回的烦恼和痛苦中解脱出来。”</p><p>佛陀说法后，出家弟子们，都再次的顶礼佛陀，他们随喜赞叹佛陀说法的无量功德，都按着佛陀所说的法去修行。</p>',9)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
